/**
 * Mint a signed genesis_session cookie from DATABASE_URL + AGENTUITY_AUTH_SECRET.
 *
 * Sources (later files override earlier; process env wins unless --force-env-file):
 *   - apps/web .env / .env.development (local default)
 *   - --env-file <path> (repeatable)
 *   - --azure-env edge|stable → infra/azure/secrets/app.env + app-<env>.env
 *
 * No AGENTUITY_EMPLOYEE_TOKEN / Ion mint-cookie / Agentuity CLI.
 *
 * Usage:
 *   pnpm exec tsx scripts/mint-dev-cookie.ts .agents/tmp/preview-auth/cookie.txt
 *   pnpm exec tsx scripts/mint-dev-cookie.ts out.txt --email you@agentuity.com
 *   pnpm exec tsx scripts/mint-dev-cookie.ts out.txt --email you@agentuity.com --azure-env edge
 *   pnpm exec tsx scripts/mint-dev-cookie.ts out.txt --email you@agentuity.com --env-file ../../infra/azure/secrets/app-edge.env
 *
 * For PR previews: mint with parent channel secrets (--azure-env edge|stable), inject
 * the host-only cookie on https://pr-N-edge|stable.agentcompany.com (same AUTH_SECRET
 * clone + Neon branch of parent DB at fork time).
 *
 * Never print the cookie value.
 */

import { execFileSync } from "node:child_process";
import { existsSync, mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { dirname, isAbsolute, join, resolve } from "node:path";
import { fileURLToPath } from "node:url";
import { parseArgs } from "node:util";

const SCRIPT_DIR = dirname(fileURLToPath(import.meta.url));
const APP_DIR = resolve(SCRIPT_DIR, "..");
const MONOREPO_ROOT = resolve(APP_DIR, "../..");

/** Prefer worktree root; fall back to primary git worktree for operator secrets. */
function monorepoRootsForSecrets(): string[] {
  const roots: string[] = [];
  const push = (p: string | undefined) => {
    if (!p) return;
    const resolved = resolve(p);
    if (!roots.includes(resolved)) roots.push(resolved);
  };
  push(process.env.GENESIS_MONOREPO_ROOT?.trim());
  push(MONOREPO_ROOT);
  try {
    const commonDir = execFileSync("git", ["rev-parse", "--git-common-dir"], {
      cwd: MONOREPO_ROOT,
      encoding: "utf8",
    }).trim();
    if (commonDir) {
      const absoluteCommon = isAbsolute(commonDir) ? commonDir : resolve(MONOREPO_ROOT, commonDir);
      // …/repo/.git → repo root (primary checkout often holds secrets/)
      push(dirname(absoluteCommon));
    }
  } catch {
    // not a git checkout; only MONOREPO_ROOT
  }
  return roots;
}

const DEFAULT_TTL_SECONDS = 3600;
const MAX_TTL_SECONDS = 86_400;

type Parsed = {
  outFile: string;
  email?: string;
  orgId?: string;
  ttlSeconds: number;
  envFiles: string[];
  azureEnv?: "edge" | "stable";
  forceEnvFile: boolean;
  help: boolean;
};

function usage(): string {
  return `Usage: mint-dev-cookie.ts <out-file> [options]

Options:
  --email <email>           app_user email (default: GENESIS_SMOKE_USER_EMAIL / GENESIS_SEED_USERS / first row)
  --org-id <org_id>         stamp claims.orgId (default: resolveLoginOrgIdForUser)
  --ttl <seconds>           cookie TTL (default ${DEFAULT_TTL_SECONDS}, max ${MAX_TTL_SECONDS})
  --env-file <path>         load KEY=VALUE file into process.env (repeatable)
  --azure-env edge|stable   load infra/azure/secrets/app.env + app-<env>.env
  --force-env-file          env files override already-set process.env
  -h, --help

Requires DATABASE_URL after env load. AGENTUITY_AUTH_SECRET is optional for
local-dev (auto-loaded from ~/.genesis/secrets after pnpm dev).
Operator keys may live in ~/.genesis/.env (shared across worktrees).
Does not use AGENTUITY_EMPLOYEE_TOKEN.
`;
}

function parseCli(argv: string[]): Parsed {
  const { values, positionals } = parseArgs({
    args: argv,
    options: {
      email: { type: "string" },
      "org-id": { type: "string" },
      ttl: { type: "string" },
      "env-file": { type: "string", multiple: true },
      "azure-env": { type: "string" },
      "force-env-file": { type: "boolean", default: false },
      help: { type: "boolean", short: "h", default: false },
    },
    allowPositionals: true,
    strict: true,
  });

  if (values.help) {
    return {
      outFile: "",
      ttlSeconds: DEFAULT_TTL_SECONDS,
      envFiles: [],
      forceEnvFile: false,
      help: true,
    };
  }

  const outFile = positionals[0]?.trim() ?? "";
  if (!outFile) {
    throw new Error(usage());
  }

  let ttlSeconds = DEFAULT_TTL_SECONDS;
  if (values.ttl !== undefined) {
    const n = Number(values.ttl);
    if (!Number.isFinite(n) || n <= 0) {
      throw new Error("ttl must be a positive number of seconds");
    }
    if (n > MAX_TTL_SECONDS) {
      throw new Error(`ttl must be at most ${MAX_TTL_SECONDS}`);
    }
    ttlSeconds = Math.floor(n);
  }

  let azureEnv: "edge" | "stable" | undefined;
  if (values["azure-env"] !== undefined) {
    const raw = values["azure-env"].trim().toLowerCase();
    if (raw !== "edge" && raw !== "stable") {
      throw new Error("--azure-env must be edge or stable");
    }
    azureEnv = raw;
  }

  const envFiles = (values["env-file"] ?? []).map((p) => p.trim()).filter(Boolean);

  return {
    outFile,
    email: values.email?.trim() || undefined,
    orgId: values["org-id"]?.trim() || undefined,
    ttlSeconds,
    envFiles,
    azureEnv,
    forceEnvFile: values["force-env-file"] === true,
    help: false,
  };
}

/** Parse dotenv-style file; set process.env keys. */
export function applyEnvFile(
  filePath: string,
  options: { optional?: boolean; override?: boolean } = {},
): void {
  const absolute = isAbsolute(filePath) ? filePath : resolve(process.cwd(), filePath);
  if (!existsSync(absolute)) {
    if (options.optional) return;
    throw new Error(`env file not found: ${absolute}`);
  }
  const text = readFileSync(absolute, "utf8");
  for (const line of text.split("\n")) {
    const trimmed = line.trim();
    if (!trimmed || trimmed.startsWith("#")) continue;
    const eq = trimmed.indexOf("=");
    if (eq <= 0) continue;
    const key = trimmed.slice(0, eq).trim();
    if (!/^[A-Za-z_][A-Za-z0-9_]*$/.test(key)) continue;
    let value = trimmed.slice(eq + 1).trim();
    if (
      (value.startsWith('"') && value.endsWith('"')) ||
      (value.startsWith("'") && value.endsWith("'"))
    ) {
      value = value.slice(1, -1);
    }
    if (!options.override && process.env[key] !== undefined && process.env[key] !== "") {
      continue;
    }
    process.env[key] = value;
  }
}

/**
 * Resolve app secret file paths for an azure channel.
 * When GENESIS_AZURE_SECRETS_DIR is set, use that directory only.
 * Otherwise search monorepo roots (worktree + primary checkout).
 */
function resolveAzureSecretFiles(azureEnv: "edge" | "stable"): string[] {
  const names = ["app.env", `app-${azureEnv}.env`];
  const overrideDir = process.env.GENESIS_AZURE_SECRETS_DIR?.trim();
  if (overrideDir) {
    return names.map((name) => join(resolve(overrideDir), name));
  }
  // Prefer a root that already has the overlay file (primary checkout secrets).
  for (const root of monorepoRootsForSecrets()) {
    const overlay = join(root, "infra/azure/secrets", `app-${azureEnv}.env`);
    const base = join(root, "infra/azure/secrets", "app.env");
    if (existsSync(overlay) || existsSync(base)) {
      return [base, overlay];
    }
  }
  // Default paths on worktree root for error messages.
  return names.map((name) => join(MONOREPO_ROOT, "infra/azure/secrets", name));
}

function loadEnvForMint(parsed: Parsed): void {
  const override = parsed.forceEnvFile;
  // Local defaults first (optional).
  applyEnvFile(join(APP_DIR, ".env"), { optional: true, override });
  applyEnvFile(join(APP_DIR, ".env.development"), { optional: true, override });
  applyEnvFile(join(APP_DIR, ".env.local"), { optional: true, override });


[122 more lines in file. Use offset=221 to continue.]

  for (const file of parsed.envFiles) {
    applyEnvFile(file, { optional: false, override });
  }

  if (parsed.azureEnv) {
    const files = resolveAzureSecretFiles(parsed.azureEnv);
    let loaded = 0;
    for (const file of files) {
      if (!existsSync(file)) {
        console.error(`note: azure secret file missing (skip): ${file}`);
        continue;
      }
      applyEnvFile(file, { optional: false, override: true });
      loaded += 1;
    }
    if (loaded === 0) {
      throw new Error(
        [
          `No azure secret files for --azure-env ${parsed.azureEnv}.`,
          `Expected at least one of:`,
          ...files.map((f) => `  ${f}`),
          "Pull secrets with infra/azure/env-secrets.sh (see infra/azure/README.md),",
          "or pass --env-file with AGENTUITY_AUTH_SECRET and DATABASE_URL.",
        ].join("\n"),
      );
    }
  }
}

async function main(): Promise<void> {
  const parsed = parseCli(process.argv.slice(2));
  if (parsed.help) {
    process.stdout.write(usage());
    return;
  }

  loadEnvForMint(parsed);

  // Local-dev: ~/.genesis/.env keys + auto secrets under ~/.genesis/secrets.
  const { loadGenesisHomeEnv } = await import("../src/lib/load-genesis-home-env");
  loadGenesisHomeEnv();
  const { ensureLocalDevSecrets } = await import("../src/lib/local-dev-secrets");
  ensureLocalDevSecrets({ appDir: APP_DIR });

  if (!process.env.AGENTUITY_AUTH_SECRET?.trim()) {
    throw new Error(
      "AGENTUITY_AUTH_SECRET is required (local .env, ~/.genesis after pnpm dev, or infra/azure/secrets/app[-env].env)",
    );
  }
  if (!process.env.DATABASE_URL?.trim()) {
    throw new Error("DATABASE_URL is required (local .env or infra/azure/secrets/app[-env].env)");
  }

  // Import after env load so db + signSession see DATABASE_URL / AUTH_SECRET.
  const { and, eq, isNull } = await import("drizzle-orm");
  const { close, db } = await import("../src/lib/db");
  const { isInternalAgentuityEmail } = await import("../src/lib/agentuity-email");
  const { appUser } = await import("../src/lib/schema");
  const { signSession } = await import("../src/lib/session-cookie");
  const { resolveLoginOrgIdForUser } = await import("../src/storage/org-membership");

  try {
    const activeUserFilter = isNull(appUser.deletedAt);
    const seedEmail = (
      parsed.email ??
      process.env.GENESIS_SMOKE_USER_EMAIL ??
      process.env.GENESIS_SEED_USERS?.split(/[\s,;]+/)[0]
    )
      ?.trim()
      .toLowerCase();

    const [user] = seedEmail
      ? await db
          .select()
          .from(appUser)
          .where(and(eq(appUser.email, seedEmail), activeUserFilter))
          .limit(1)
      : await db.select().from(appUser).where(activeUserFilter).limit(1);

    if (!user) {
      console.error(seedEmail ? `No appUser row for ${seedEmail}` : "No appUser rows found");
      process.exitCode = 2;
      return;
    }

    const orgId = parsed.orgId?.trim() || (await resolveLoginOrgIdForUser(user.id)) || null;
    const now = Math.floor(Date.now() / 1000);
    const token = signSession({
      sub: user.id,
      ion_user_id: user.ionUserId,
      email: user.email,
      iat: now,
      exp: now + parsed.ttlSeconds,
      v: 1,
      orgId,
      employee: isInternalAgentuityEmail(user.email) ? true : undefined,
    });

    const outPath = isAbsolute(parsed.outFile)
      ? parsed.outFile
      : resolve(process.cwd(), parsed.outFile);
    mkdirSync(dirname(outPath), { recursive: true });
    writeFileSync(outPath, token, { mode: 0o600 });

    const secretSource = parsed.azureEnv
      ? `azure-env=${parsed.azureEnv}`
      : parsed.envFiles.length > 0
        ? `env-file (${parsed.envFiles.length})`
        : "process/local .env";
    console.log(
      `wrote cookie for ${user.email} orgId=${orgId ?? "null"} ttl=${parsed.ttlSeconds}s source=${secretSource} → ${outPath}`,
    );
  } finally {
    await close();
  }
}

main().catch((error: unknown) => {
  console.error(error instanceof Error ? error.message : String(error));
  process.exit(1);
});

