export function stableStringify(value: unknown): string {
  if (value === null || typeof value !== "object") {
    return JSON.stringify(value);
  }
  if (Array.isArray(value)) {
    return `[${value.map((entry) => stableStringify(entry)).join(",")}]`;
  }
  const object = value as Record<string, unknown>;
  const keys = Object.keys(object).sort();
  return `{${keys.map((key) => `${JSON.stringify(key)}:${stableStringify(object[key])}`).join(",")}}`;
}

export function normalizeManifestContent(raw: string): string {
  return stableStringify(JSON.parse(raw) as unknown);
}

/**
 * Stable sha256 over package files + oauth-provider mcp_config (when present).
 * Fixture mcp_config changes must re-sync even if package files are unchanged.
 */
export function computeConnectionTemplateContentHash(
  files: readonly ConnectionTemplateFile[],
  options?: { slug?: string },
): string {
  const sorted = [...files].sort((left, right) =>
    left.relativePath.localeCompare(right.relativePath),
  );
  const hash = createHash("sha256");
  for (const file of sorted) {
    const content =
      file.relativePath === "manifest.json" ? normalizeManifestContent(file.content) : file.content;
    hash.update(file.relativePath);
    hash.update("\0");
    hash.update(content);
    hash.update("\0");
  }
  if (options?.slug) {
    const mcpFragment = oauthProviderMcpConfigHashFragment(options.slug);
    if (mcpFragment) {
      hash.update("oauth-mcp\0");
      hash.update(mcpFragment);
      hash.update("\0");
    }
  }
  return hash.digest("hex");
}

