function validateMcpRequestHeaders(
  request: Request,
  policy: Pick<
    WebStandardStreamableHTTPServerTransportOptions,
    "allowedHosts" | "allowedOrigins" | "enableDnsRebindingProtection"
  >,
): Response | undefined {
  if (!policy.enableDnsRebindingProtection) return undefined;
  const host = request.headers.get("host");
  if (policy.allowedHosts?.length && (!host || !policy.allowedHosts.includes(host))) {
    return Response.json(
      {
        jsonrpc: "2.0",
        error: { code: -32000, message: `Invalid Host header: ${host}` },
        id: null,
      },
      { status: 403 },
    );
  }
  const origin = request.headers.get("origin");
  if (origin && policy.allowedOrigins?.length && !policy.allowedOrigins.includes(origin)) {
    return Response.json(
      {
        jsonrpc: "2.0",
        error: { code: -32000, message: `Invalid Origin header: ${origin}` },
        id: null,
      },
      { status: 403 },
    );
  }
  return undefined;
}

