async pullRecords(entityId: string, cursor: string | null): Promise<PullRecordsResult> {
  const path = CALLRAIL_ENTITY_PATH[entityId];
  if (!path)
    throw new IntegrationSyncError("entity_not_found", `Unknown CallRail entity ${entityId}`);
  const accountId = await this.resolveAccountId();
  const query = new URLSearchParams({ per_page: String(CALLRAIL_PAGE_SIZE) });
  if (cursor) query.set("page", cursor);
  const body = await this.request<{
    calls?: unknown[];
    text_messages?: unknown[];
    form_submissions?: unknown[];
  }>(`/a/${accountId}/${path}?${query}`);
  const rows = (body.calls ?? body.text_messages ?? body.form_submissions ?? [])
    .flatMap((row) => (isCallRailRow(row) ? [callrailRowToRemoteRecord(row)] : []))
    .filter((row): row is NonNullable<typeof row> => row !== null);
  return {
    rows,
    nextCursor: rows.length === CALLRAIL_PAGE_SIZE ? String(Number(cursor ?? "1") + 1) : null,
  };
}

private async resolveAccountId(): Promise<string> {
  const accounts = await this.request<{ accounts?: Array<{ id?: string | number }> }>("/a.json");
  const id = accounts.accounts?.[0]?.id;
  if (id === undefined)
    throw new IntegrationSyncError(
      "provider_error",
      "CallRail API key has no accessible accounts",
    );
  return String(id);
}

