import { IntegrationSyncError } from "../../../domain/integration-sync";
import type { PullRecordsResult } from "../types";
import { CALLRAIL_API_BASE_URL, CALLRAIL_ENTITY_PATH, CALLRAIL_PAGE_SIZE } from "./constants";
import { callrailColumnsForEntity, callrailRowToRemoteRecord, isCallRailRow } from "./mappers";

export class CallRailSyncClient {
  private readonly fetchImpl: typeof fetch;
  private readonly baseUrl: string;
  private readonly accessToken: string;

  constructor(options: { accessToken: string; fetchImpl?: typeof fetch; baseUrl?: string }) {
    this.accessToken = options.accessToken;
    this.fetchImpl = options.fetchImpl ?? fetch;
    this.baseUrl = (options.baseUrl ?? CALLRAIL_API_BASE_URL).replace(/\/$/, "");
  }

  columnsForEntity(entityId: string) {
    const columns = callrailColumnsForEntity(entityId);
    if (columns.length === 0)
      throw new IntegrationSyncError("entity_not_found", `Unknown CallRail entity ${entityId}`);
    return columns;
  }

  async pullRecords(entityId: string, cursor: string | null): Promise<PullRecordsResult> {
    const path = CALLRAIL_ENTITY_PATH[entityId];
    if (!path)
      throw new IntegrationSyncError("entity_not_found", `Unknown CallRail entity ${entityId}`);

    const [accountPage, accountIndex, entityPage] = this.decodeCursor(cursor);
    const accountsResponse = await this.request<{
      accounts?: Array<{ id?: string | number }>;
    }>(`/a.json?per_page=${CALLRAIL_PAGE_SIZE}&page=${accountPage}`);
    const accounts = (accountsResponse.accounts ?? []).filter(
      (account): account is { id: string | number } =>
        typeof account.id === "string" || typeof account.id === "number",
    );
    const account = accounts[accountIndex];
    if (!account) {
      if (accountPage === 1 && accountIndex === 0) {
        throw new IntegrationSyncError(
          "provider_error",
          "CallRail API key has no accessible accounts",
        );
      }
      return { rows: [], nextCursor: null };
    }

    const query = new URLSearchParams({
      per_page: String(CALLRAIL_PAGE_SIZE),
      page: String(entityPage),
    });
    const body = await this.request<{
      calls?: unknown[];
      conversations?: unknown[];
      form_submissions?: unknown[];
    }>(`/a/${account.id}/${path}?${query}`);
    const rawRows = body.calls ?? body.conversations ?? body.form_submissions ?? [];
    const rows = rawRows
      .flatMap((row) =>
        isCallRailRow(row) ? [callrailRowToRemoteRecord(row, String(account.id))] : [],
      )
      .filter((row): row is NonNullable<typeof row> => row !== null);

    return {
      rows,
      nextCursor: this.nextCursor(
        accountPage,
        accountIndex,
        entityPage,
        accounts.length,
        rawRows.length === CALLRAIL_PAGE_SIZE,
      ),
    };
  }

  private decodeCursor(
    cursor: string | null,
  ): [accountPage: number, accountIndex: number, entityPage: number] {
    if (!cursor) return [1, 0, 1];
    const values = cursor.split(":").map(Number);
    if (
      values.length !== 3 ||
      !Number.isInteger(values[0]) ||
      values[0]! < 1 ||
      !Number.isInteger(values[1]) ||
      values[1]! < 0 ||
      !Number.isInteger(values[2]) ||
      values[2]! < 1
    ) {
      throw new IntegrationSyncError("provider_error", "Invalid CallRail sync cursor");
    }
    return [values[0]!, values[1]!, values[2]!];
  }

  private nextCursor(
    accountPage: number,
    accountIndex: number,
    entityPage: number,
    accountCount: number,
    entityHasMore: boolean,
  ): string | null {
    if (entityHasMore) return `${accountPage}:${accountIndex}:${entityPage + 1}`;
    if (accountIndex + 1 < accountCount) return `${accountPage}:${accountIndex + 1}:1`;
    if (accountCount === CALLRAIL_PAGE_SIZE) return `${accountPage + 1}:0:1`;
    return null;
  }

  private async request<T>(path: string): Promise<T> {
    const response = await this.fetchImpl(`${this.baseUrl}${path}`, {
      headers: { Authorization: `Token token="${this.accessToken}"`, Accept: "application/json" },
      signal: AbortSignal.timeout(15_000),
    });
    if (response.status === 401 || response.status === 403)
      throw new IntegrationSyncError("not_connected", "CallRail API key was rejected");
    if (response.status === 429)
      throw new IntegrationSyncError("provider_error", "CallRail rate limit exceeded");
    if (!response.ok)
      throw new IntegrationSyncError("provider_error", `CallRail API error (${response.status})`);
    return response.json() as Promise<T>;
  }
}

import type { RemoteColumnDescriptor, RemoteRecord } from "../types";
import {
  CALLRAIL_CALLS_ENTITY_ID,
  CALLRAIL_FORM_SUBMISSIONS_ENTITY_ID,
  CALLRAIL_TEXT_MESSAGES_ENTITY_ID,
} from "./constants";

type CallRailRow = Record<string, unknown>;

export function isCallRailRow(value: unknown): value is CallRailRow {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

const columns: Record<string, RemoteColumnDescriptor[]> = {};

// Keep the provider fields immutable: CallRail's documented v3 endpoints are read surfaces.
for (const [entityId, names] of Object.entries({
  [CALLRAIL_CALLS_ENTITY_ID]: [
    "id",
    "customer_name",
    "customer_phone_number",
    "tracking_phone_number",
    "start_time",
    "duration",
    "direction",
    "status",
    "recording",
    "campaign_name",
  ],
  [CALLRAIL_TEXT_MESSAGES_ENTITY_ID]: [
    "id",
    "company_id",
    "customer_name",
    "customer_phone_number",
    "last_message_at",
    "state",
    "recent_messages",
  ],
  [CALLRAIL_FORM_SUBMISSIONS_ENTITY_ID]: [
    "id",
    "company_id",
    "person_id",
    "form_data",
    "form_url",
    "landing_page_url",
    "referrer",
    "referring_url",
    "submitted_at",
    "customer_phone_number",
    "customer_name",
    "customer_email",
  ],
})) {
  columns[entityId] = names.map((name) => ({
    id: name,
    name,
    type: "text",
    nullable: true,
    schemaLocked: true,
    valueReadOnly: true,
  }));
}

export function callrailColumnsForEntity(entityId: string): RemoteColumnDescriptor[] {
  return columns[entityId] ?? [];
}

export function callrailRowToRemoteRecord(
  row: CallRailRow,
  accountId?: string,
): RemoteRecord | null {
  const id = typeof row.id === "string" || typeof row.id === "number" ? String(row.id) : null;
  if (!id) return null;
  const values = Object.fromEntries(
    Object.entries(row).map(([key, value]) => [
      key,
      typeof value === "object" && value !== null ? JSON.stringify(value) : value,
    ]),
  );
  return {
    externalId: accountId ? `${accountId}:${id}` : id,
    values,
    externalUpdatedAt:
      typeof row.submitted_at === "string"
        ? row.submitted_at
        : typeof row.updated_at === "string"
          ? row.updated_at
          : typeof row.last_message_at === "string"
            ? row.last_message_at
            : typeof row.start_time === "string"
              ? row.start_time
              : typeof row.created_at === "string"
                ? row.created_at
                : null,
  };
}

{
  "id": "connection:callrail",
  "name": "CallRail",
  "description": "Call tracking, text messages, and form submissions through the CallRail REST API.",
  "connections": ["callrail"],
  "runtime": {
    "delivery": {
      "callrail": {
        "as": "env",
        "envKey": "CALLRAIL_API_KEY"
      }
    }
  }
}

